/**
 * Idempotent postinstall patch for @capacitor-community/native-audio on Android.
 *
 * The plugin's handleOnPause adds still-playing assets to resumeList. stop() and
 * unload() did not remove those entries, so if the activity paused before our
 * JS stop() landed, handleOnResume briefly restarted music after music-off /
 * stopMusic(). Clearing resumeList on stop/unload closes that race.
 *
 * capacitor.settings.gradle points at node_modules and is regenerated by cap sync,
 * so the durable fix lives here rather than in the android/ tree.
 */

const fs = require('fs');
const path = require('path');

const MARKER = 'tictacdoh: clear resumeList on stop/unload';

function isNativeAudioAndroidPatched(source) {
  return (
    source.includes(MARKER) &&
    /asset\.stop\(\);[\s\S]*?resumeList\.remove\(asset\);/.test(source) &&
    /asset\.unload\(\);[\s\S]*?resumeList\.remove\(asset\);/.test(source)
  );
}

function applyNativeAudioAndroidPatch(source) {
  if (isNativeAudioAndroidPatched(source)) {
    return source;
  }

  let next = source;
  let changed = false;

  const stopPatched = next.replace(
    /(^[ \t]*)asset\.stop\(\);\s*\n([ \t]*)call\.resolve\(\);/m,
    (match, indentStop, indentResolve) => {
      changed = true;
      return (
        `${indentStop}asset.stop();\n` +
        `${indentStop}// ${MARKER}\n` +
        `${indentStop}if (resumeList != null) {\n` +
        `${indentStop}    resumeList.remove(asset);\n` +
        `${indentStop}}\n` +
        `${indentResolve}call.resolve();`
      );
    }
  );
  if (stopPatched === next) {
    throw new Error(
      'patch-native-audio-android: stop() body not found — plugin source may have changed; update scripts/patch-native-audio-android.js'
    );
  }
  next = stopPatched;

  const unloadPatched = next.replace(
    /(^[ \t]*)asset\.unload\(\);\s*\n([ \t]*)audioAssetList\.remove\(audioId\);/m,
    (match, indentUnload, indentRemove) => {
      changed = true;
      return (
        `${indentUnload}asset.unload();\n` +
        `${indentUnload}// ${MARKER}\n` +
        `${indentUnload}if (resumeList != null) {\n` +
        `${indentUnload}    resumeList.remove(asset);\n` +
        `${indentUnload}}\n` +
        `${indentRemove}audioAssetList.remove(audioId);`
      );
    }
  );
  if (unloadPatched === next) {
    throw new Error(
      'patch-native-audio-android: unload() body not found — plugin source may have changed; update scripts/patch-native-audio-android.js'
    );
  }
  next = unloadPatched;

  if (!changed) {
    throw new Error('patch-native-audio-android: no changes applied');
  }

  return next;
}

function pluginJavaPath(rootDir = path.join(__dirname, '..')) {
  return path.join(
    rootDir,
    'node_modules/@capacitor-community/native-audio/android/src/main/java/com/getcapacitor/community/audio/NativeAudio.java'
  );
}

function patchInstalledPlugin(rootDir = path.join(__dirname, '..')) {
  const target = pluginJavaPath(rootDir);
  if (!fs.existsSync(target)) {
    console.warn(`patch-native-audio-android: skip — missing ${target}`);
    return { patched: false, path: target };
  }

  const before = fs.readFileSync(target, 'utf8');
  const after = applyNativeAudioAndroidPatch(before);
  if (after !== before) {
    fs.writeFileSync(target, after);
    console.info(`patch-native-audio-android: patched ${target}`);
  }
  return { patched: true, path: target, changed: after !== before };
}

module.exports = {
  MARKER,
  applyNativeAudioAndroidPatch,
  isNativeAudioAndroidPatched,
  pluginJavaPath,
  patchInstalledPlugin,
};

if (require.main === module) {
  patchInstalledPlugin();
}
